    "name": "HRet_Valor_Total_Retenido",
    "expr": "VAR _Old = CALCULATE(\n    VAR _con_plan = SUMX(FILTER('retenciones_beneficios', NOT ISBLANK('retenciones_beneficios'[VALOR_PLAN_ACTUAL])), 'retenciones_beneficios'[VALOR_PLAN_ACTUAL])\n    VAR _sin_plan = SUMX(FILTER('retenciones_beneficios', ISBLANK('retenciones_beneficios'[VALOR_PLAN_ACTUAL])), 'retenciones_beneficios'[ARPU_INTERNET])\n    RETURN _con_plan + IF(NOT ISBLANK(_sin_plan), _sin_plan, 0),\n    'retenciones_beneficios'[es_excluido] = FALSE(), KEEPFILTERS('retenciones_beneficios'[Fecha_de_Ingreso] < DATE(2026,7,1))\n)\nVAR _NewAccounts = CALCULATETABLE(VALUES('retenciones_beneficios'[Cuenta]), 'retenciones_beneficios'[es_excluido] = FALSE(), KEEPFILTERS('retenciones_beneficios'[Fecha_de_Ingreso] >= DATE(2026,7,1)))\nVAR _New = SUMX(\n    _NewAccounts,\n    VAR _tieneP = CALCULATE(COUNTROWS('retenciones_beneficios'), NOT ISBLANK('retenciones_beneficios'[VALOR_PLAN_ACTUAL]), 'retenciones_beneficios'[es_excluido] = FALSE(), KEEPFILTERS('retenciones_beneficios'[Fecha_de_Ingreso] >= DATE(2026,7,1))) > 0\n    VAR _fP = CALCULATE(MAX('retenciones_beneficios'[Fecha_de_Ingreso]), NOT ISBLANK('retenciones_beneficios'[VALOR_PLAN_ACTUAL]), 'retenciones_beneficios'[es_excluido] = FALSE(), KEEPFILTERS('retenciones_beneficios'[Fecha_de_Ingreso] >= DATE(2026,7,1)))\n    VAR _vP = CALCULATE(MAX('retenciones_beneficios'[VALOR_PLAN_ACTUAL]), 'retenciones_beneficios'[Fecha_de_Ingreso] = _fP)\n    VAR _fA = CALCULATE(MAX('retenciones_beneficios'[Fecha_de_Ingreso]), NOT ISBLANK('retenciones_beneficios'[ARPU_INTERNET]), 'retenciones_beneficios'[es_excluido] = FALSE(), KEEPFILTERS('retenciones_beneficios'[Fecha_de_Ingreso] >= DATE(2026,7,1)))\n    VAR _vA = CALCULATE(MAX('retenciones_beneficios'[ARPU_INTERNET]), 'retenciones_beneficios'[Fecha_de_Ingreso] = _fA)\n    RETURN IF(_tieneP, _vP, _vA)\n)\nRETURN _Old + _New"
