    "expr": "VAR _k = SELECTEDVALUE ( 'Mes Transcurrido'[Mes] )\nVAR _baseObs =\n    CALCULATE (\n        COUNTROWS ( cascada_retenidos_detalle ),\n        cascada_retenidos_detalle[vigente_mes_0] = 1,\n        cascada_retenidos_detalle[meses_observados] >= _k\n    )\nRETURN\n    IF ( ISBLANK ( _k ) || _k < 1, BLANK (), DIVIDE ( [Casc_Vigentes], _baseObs ) )"
