    "expr": "VAR _esc = SELECTEDVALUE ( 'Escenario Suspension'[Id], 0 )\nVAR _tipos = VALUES ( 'Tipo Salida'[detalle_salida] )\nRETURN\n    AVERAGEX (\n        FILTER (\n            cascada_retenidos_detalle,\n            cascada_retenidos_detalle[vigente_mes_0] = 1\n                && cascada_retenidos_detalle[meses_observados] = 12\n        ),\n        VAR _ms =\n            SWITCH ( _esc,\n                    1, cascada_retenidos_detalle[mes_salida_si_susp_desercion_baja],\n                    2, cascada_retenidos_detalle[mes_salida_si_desercion_y_pago_baja],\n                    3, cascada_retenidos_detalle[mes_salida_si_toda_susp_baja],\n                    cascada_retenidos_detalle[mes_salida]\n                )\n        RETURN\n            IF ( NOT ISBLANK ( _ms ) && ( ISBLANK ( cascada_retenidos_detalle[detalle_salida] ) || cascada_retenidos_detalle[detalle_salida] IN _tipos ), _ms, 12 )\n    )"
